8	// 本文件回归保障分批使用在“业务拒绝—修正后沿用原编号重试”场景下的编号规则：
9	// 使用编号的内容只由首次成功的使用确定；一次新使用因为超过本笔承诺的未用
10	// 数量而被 ErrUsageExceeded 整次拒绝时，不能先扣掉允许使用的部分，也不能提前
11	// 占住使用编号——既不把编号绑定到这笔承诺，也不把被拒绝的数量记成冲突内容。
12	// 调用方随后沿用同一编号、仍指向同一承诺、只把数量改成合法值即可成功；即使
13	// 仓库实物仍充足，也不能借用其他承诺的未用余量。成功后原样重试取回首次的
14	// 使用记录，再改回曾被业务拒绝的数量则按 ErrConflict 处理，成功结果保留。
15	//
16	// 主例数据（与用户描述一致）：备件 part1 初始库存 12 件；请求 r1 的承诺 c1
17	// 预留 5 件、已用 2 件（未用 3 件）；请求 r2 的承诺 c2 预留 4 件、尚未使用
18	// （未用 4 件）。两笔承诺共用同一备件、分属不同请求，均未取消、未到期。
19	// 此时实物剩余 10 件，有效占用 7 件（3+4），可承诺 3 件。
20	
21	// exceededRetryStore 构造主例初始状态：part1 初始 12 件，c1（属于 r1）预留
22	// 5 件并已成功使用 2 件，c2（属于 r2）预留 4 件尚未使用。两笔承诺到期时刻
23	// 相同且晚于全部操作时刻。
24	func exceededRetryStore(t *testing.T) *Store {
25		t.Helper()
26		s := NewStore()
27		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
28			t.Fatalf("register product: %v", err)
29		}
30		if err := s.RegisterPart("part1", 12); err != nil {
31			t.Fatalf("register part: %v", err)
32		}
33		if err := s.SubmitRequest("r1", "p1", "NOISE"); err != nil {
34			t.Fatalf("submit request r1: %v", err)
35		}
36		if err := s.SubmitRequest("r2", "p1", "NOISE"); err != nil {
37			t.Fatalf("submit request r2: %v", err)
38		}
39		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
40			t.Fatalf("reserve c1: %v", err)
41		}
42		if _, err := s.Reserve("c2", "r2", "part1", 4, expiryOK, nowOK); err != nil {
43			t.Fatalf("reserve c2: %v", err)
44		}
45		if _, err := s.Use("uSeed", "c1", 2, nowOK); err != nil {
46			t.Fatalf("seed use 2 from c1: %v", err)
47		}
48		return s
