51	// assertExceededBaseline 断言业务拒绝前后的主例状态：实物 10、有效占用 7
52	// （c1 未用 3 + c2 未用 4）、可承诺 3；c1 仍是原定 5、已用 2、未用 3 且
53	// 归属于 r1，c2 仍是原定 4、已用 0、未用 4 且归属于 r2，两笔均有效。
54	func assertExceededBaseline(t *testing.T, s *Store) {
55		t.Helper()
56		assertPartAccount(t, s, 10, 7, 3)
57	
58		st, err := s.PartStatus("part1", nowOK)
59		if err != nil {
