1	package warranty
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// expStore 构造一个带产品（保修 30 天）、指定库存备件和两个合格请求的仓库。
10	func expStore(t *testing.T, stock int) *Store {
11		t.Helper()
12		s := NewStore()
13		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
14			t.Fatalf("register product: %v", err)
15		}
16		if err := s.RegisterPart("part1", stock); err != nil {
17			t.Fatalf("register part: %v", err)
18		}
19		if err := s.SubmitRequest("r1", "p1", "FAULTY"); err != nil {
20			t.Fatalf("submit r1: %v", err)
21		}
22		if err := s.SubmitRequest("r2", "p1", "FAULTY"); err != nil {
23			t.Fatalf("submit r2: %v", err)
24		}
25		return s
26	}
27	
28	func detailByID(st *PartStatus, id string) (CommitmentDetail, bool) {
29		for _, d := range st.Details {
30			if d.CommitmentID == id {
31				return d, true
32			}
33		}
34		return CommitmentDetail{}, false
35	}
36	
37	// TestExpiryReleaseSurvivesClockRollback 对应用户给出的主例：实物库存五件，
38	// 甲预留五件并于十二点到期；十二点零一分乙又预留同一备件五件；此后用
39	// 十一点五十九分查询或使用，甲不得重新占用或继续扣减。
40	func TestExpiryReleaseSurvivesClockRollback(t *testing.T) {
41		s := expStore(t, 5)
42		noon := t0.Add(10 * day)
43		before := noon.Add(-time.Minute)
44		after := noon.Add(time.Minute)
45	
46		// 甲预留五件，十二点到期。
47		first, err := s.Reserve("jia", "r1", "part1", 5, noon, before)
48		if err != nil {
49			t.Fatalf("reserve jia: %v", err)
50		}
51		// 十二点零一分为合格请求创建乙：甲到期释放，乙能预留同一批五件。
52		if _, err := s.Reserve("yi", "r2", "part1", 5, expiryOK, after); err != nil {
53			t.Fatalf("reserve yi after jia expiry: %v", err)
54		}
55	
56		// 用十一点五十九分查询：甲已永久到期，只看到乙占用五件，可承诺为零。
57		st, err := s.PartStatus("part1", before)
58		if err != nil {
59			t.Fatalf("part status at earlier time: %v", err)
60		}
61		if st.PhysicalRemaining != 5 || st.ActiveOccupied != 5 || st.Committable != 0 {
62			t.Fatalf("rollback stock: phys=%d occupied=%d committable=%d, want 5/5/0",
63				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
64		}
65		dj, ok := detailByID(st, "jia")
66		if !ok || dj.Status != CommitmentExpired || dj.RemainingQuantity != 5 {
67			t.Fatalf("jia at rollback: %+v ok=%v, want expired/remaining=5", dj, ok)
68		}
69		dy, _ := detailByID(st, "yi")
70		if dy.Status != CommitmentActive || dy.RemainingQuantity != 5 {
71			t.Fatalf("yi at rollback: %+v, want active/remaining=5", dy)
72		}
73	
74		// 请求视图在较早时刻也保持甲到期。
75		view, err := s.RequestView("r1", before)
76		if err != nil {
77			t.Fatalf("request view: %v", err)
78		}
79		var foundJia bool
80		for _, d := range view.Commitments {
81			if d.CommitmentID == "jia" {
82				foundJia = true
83				if d.Status != CommitmentExpired || d.OriginalQuantity != 5 ||
84					d.UsedQuantity != 0 || d.RemainingQuantity != 5 || !d.Expiry.Equal(noon) {
85					t.Fatalf("jia detail at rollback: %+v", d)
86				}
87			}
88		}
89		if !foundJia {
90			t.Fatal("jia missing from request view")
91		}
92	
93		// 尝试在十一点五十九分使用甲：一律拒绝，且不改变乙的占用与实物数量。
94		if _, err := s.Use("u-jia", "jia", 1, before); !errors.Is(err, ErrCommitmentClosed) {
95			t.Fatalf("use jia after rollback: got %v, want ErrCommitmentClosed", err)
96		}
97		st2, _ := s.PartStatus("part1", before)
98		if st2.PhysicalRemaining != 5 || st2.ActiveOccupied != 5 || st2.Committable != 0 {
99			t.Fatalf("failed jia use changed stock: %+v", st2)
100		}
101		cj, _ := s.Commitment("jia")
102		if cj.Used != 0 || !cj.Expired || cj.Canceled {
103			t.Fatalf("jia mutated by failed use: %+v", cj)
104		}
105		cy, _ := s.Commitment("yi")
106		if cy.Used != 0 || cy.Expired || cy.Canceled {
107			t.Fatalf("yi mutated by failed jia use: %+v", cy)
108		}
109	
110		// 时钟回退不影响正常承诺：乙在较早时刻仍可使用。
111		if _, err := s.Use("u-yi", "yi", 1, before); err != nil {
112			t.Fatalf("use yi at earlier time: %v", err)
113		}
114		st3, _ := s.PartStatus("part1", before)
115		if st3.PhysicalRemaining != 4 || st3.ActiveOccupied != 4 {
116			t.Fatalf("yi use: phys=%d occupied=%d, want 4/4", st3.PhysicalRemaining, st3.ActiveOccupied)
117		}
118		// 首次预留快照不反映这些变化。
119		if first.Used != 0 || first.Expired || first.Canceled {
120			t.Fatalf("first snapshot changed: %+v", first)
121		}
122	}
