105	// TestCommitmentUsagesFailuresLeaveNoTrace 锁定失败提交不进明细：超量领取、
106	// 沿用成功编号改数量或改承诺的冲突提交，都不能出现在成功明细中，也不能覆盖
107	// 原成功记录；尚未成功的编号先失败后成功时，只展示后来成功绑定的承诺与数量。
108	func TestCommitmentUsagesFailuresLeaveNoTrace(t *testing.T) {
109		s := usagesMainStore(t)
110	
111		if _, err := s.Use("U-B", "cMain", 2, nowOK); err != nil {
112			t.Fatalf("use U-B 2 from cMain: %v", err)
113		}
114		// 超量失败：cMain 未用 4 件，申请 5 件整次失败，不产生记录。
115		if _, err := s.Use("U-X", "cMain", 5, nowOK); !errors.Is(err, ErrUsageExceeded) {
