117		}
118		// 沿用成功编号 U-B 改数量、改承诺：均按冲突处理，不覆盖原记录。
119		if _, err := s.Use("U-B", "cMain", 3, nowOK); !errors.Is(err, ErrConflict) {
120			t.Fatalf("U-B with changed quantity: got %v, want ErrConflict", err)
121		}
122		if _, err := s.Use("U-B", "cOther", 2, nowOK); !errors.Is(err, ErrConflict) {
123			t.Fatalf("U-B with changed commitment: got %v, want ErrConflict", err)
124		}
125		// 尚未成功的编号 U-X 先因数量不合法失败，再超量失败，最后合法成功：
126		// 明细只展示成功绑定的内容。
127		if _, err := s.Use("U-X", "cMain", 0, nowOK); !errors.Is(err, ErrInvalidParam) {
128			t.Fatalf("U-X zero quantity: got %v, want ErrInvalidParam", err)
129		}
130		if _, err := s.Use("U-X", "cMain", 5, nowOK); !errors.Is(err, ErrUsageExceeded) {
131			t.Fatalf("U-X over use: got %v, want ErrUsageExceeded", err)
132		}
133		if _, err := s.Use("U-X", "cMain", 1, nowOK); err != nil {
134			t.Fatalf("U-X legal use: %v", err)
135		}
136		// 尚未成功的编号 U-Y 在 cMain 上超量失败后，成功发生在 cOther 上：
137		// 记录只属于 cOther，cMain 不得出现 U-Y。
138		if _, err := s.Use("U-Y", "cMain", 5, nowOK); !errors.Is(err, ErrUsageExceeded) {
139			t.Fatalf("U-Y over use on cMain: got %v, want ErrUsageExceeded", err)
140		}
141		if _, err := s.Use("U-Y", "cOther", 1, nowOK); err != nil {
142			t.Fatalf("U-Y success on cOther: %v", err)
143		}
144	
145		us, err := s.CommitmentUsages("cMain")
146		if err != nil {
147			t.Fatalf("commitment usages cMain: %v", err)
148		}
149		want := []Usage{
150			{ID: "U-B", CommitmentID: "cMain", Quantity: 2},
151			{ID: "U-X", CommitmentID: "cMain", Quantity: 1},
152		}
153		if len(us) != len(want) {
154			t.Fatalf("usages = %+v, want %+v", us, want)
155		}
156		for i, u := range us {
157			if u != want[i] {
158				t.Fatalf("usages[%d] = %+v, want %+v", i, u, want[i])
159			}
160		}
161		if got, err := s.CommitmentUsages("cOther"); err != nil ||
162			len(got) != 1 || got[0] != (Usage{ID: "U-Y", CommitmentID: "cOther", Quantity: 1}) {
163			t.Fatalf("cOther usages = %+v err %v, want only {U-Y cOther 1}", got, err)
164		}
165		// 原成功记录未被失败提交覆盖：U-B 原样重试仍取回两件。
166		if got, err := s.Use("U-B", "cMain", 2, nowOK); err != nil || got.Quantity != 2 {
167			t.Fatalf("U-B retry after conflicts = %+v err %v, want two-piece record", got, err)
168		}
169	}
170	
171	// TestCommitmentUsagesSurviveCloseAndCancel 锁定明细记录的是已领取的事实：
172	// 全部使用、取消、已确认到期都不清除成功记录，释放的未用数量不算领取量；
173	// 查询已关闭承诺仍成功，关闭后被拒绝的新领取不增加记录。
174	func TestCommitmentUsagesSurviveCloseAndCancel(t *testing.T) {
175		s := usagesMainStore(t)
176	
177		if _, err := s.Use("U-1", "cMain", 2, nowOK); err != nil {
178			t.Fatalf("use U-1: %v", err)
179		}
180		// 取消 cMain：释放未用 4 件，但已领取的 2 件记录保留。
181		if _, err := s.Cancel("cMain", nowOK); err != nil {
182			t.Fatalf("cancel cMain: %v", err)
183		}
184		// 取消后新领取被拒绝，不增加记录。
185		if _, err := s.Use("U-2", "cMain", 1, nowOK); !errors.Is(err, ErrCommitmentClosed) {
186			t.Fatalf("use on canceled cMain: got %v, want ErrCommitmentClosed", err)
187		}
188		us, err := s.CommitmentUsages("cMain")
189		if err != nil {
190			t.Fatalf("usages of canceled cMain: %v", err)
191		}
192		if len(us) != 1 || us[0] != (Usage{ID: "U-1", CommitmentID: "cMain", Quantity: 2}) {
193			t.Fatalf("canceled cMain usages = %+v, want only {U-1 cMain 2}", us)
194		}
195	
196		// cOther 用满 3 件后确认到期：全部使用与到期都不清除记录。
197		if _, err := s.Use("U-3", "cOther", 3, nowOK); err != nil {
198			t.Fatalf("use U-3: %v", err)
199		}
200		// 借新使用按当前时刻确认 cRival 到期（cRival 尚未使用，到期后无记录）。
201		if _, err := s.Use("U-4", "cRival", 1, expiryOK); !errors.Is(err, ErrCommitmentClosed) {
202			t.Fatalf("use on expiring cRival: got %v, want ErrCommitmentClosed", err)
203		}
204		// cOther 也已到到期时刻，借库存查询确认其到期。
205		if _, err := s.PartStatus("part1", expiryOK); err != nil {
206			t.Fatalf("part status at expiry: %v", err)
207		}
208		if c := mustCommitment(t, s, "cOther"); !c.Expired {
209			t.Fatalf("cOther should be confirmed expired: %+v", c)
210		}
211		got, err := s.CommitmentUsages("cOther")
212		if err != nil {
213			t.Fatalf("usages of expired cOther: %v", err)
214		}
215		if len(got) != 1 || got[0] != (Usage{ID: "U-3", CommitmentID: "cOther", Quantity: 3}) {
216			t.Fatalf("expired cOther usages = %+v, want only {U-3 cOther 3}", got)
217		}
218		// cRival 到期释放的是未用数量，没有成功领取，明细为空而非把释放量算成领取。
219		got, err = s.CommitmentUsages("cRival")
220		if err != nil {
221			t.Fatalf("usages of expired cRival: %v", err)
222		}
223		if len(got) != 0 {
224			t.Fatalf("expired cRival usages = %+v, want empty", got)
225		}
226	}
227	
228	// TestCommitmentUsagesParamAndEmpty 锁定参数与空结果规则：空承诺编号返回
229	// ErrInvalidParam，非空但不存在的承诺返回 ErrNotFound，已有承诺尚无成功
230	// 使用时返回成功和空列表。
231	func TestCommitmentUsagesParamAndEmpty(t *testing.T) {
232		s := usagesMainStore(t)
233	
234		if _, err := s.CommitmentUsages(""); !errors.Is(err, ErrInvalidParam) {
235			t.Fatalf("empty commit id: got %v, want ErrInvalidParam", err)
236		}
237		if _, err := s.CommitmentUsages("cMissing"); !errors.Is(err, ErrNotFound) {
238			t.Fatalf("unknown commit id: got %v, want ErrNotFound", err)
239		}
240		us, err := s.CommitmentUsages("cMain")
241		if err != nil {
242			t.Fatalf("usages of fresh cMain: %v", err)
243		}
244		if len(us) != 0 {
245			t.Fatalf("fresh cMain usages = %+v, want empty list", us)
246		}
247	}
248	
249	// TestCommitmentUsagesReadOnlyAndIsolated 锁定查询只读且结果独立：查询不扣减
250	// 实物库存、不释放占用、不按时刻确认到期、不追加预留处理历史；调用方修改
251	// 返回列表中的编号或数量、删减或追加内容，都不影响真实记录、已用数量、后续
252	// 查询与原样重试取回的内容。
253	func TestCommitmentUsagesReadOnlyAndIsolated(t *testing.T) {
254		s := usagesMainStore(t)
255	
256		if _, err := s.Use("U-1", "cMain", 2, nowOK); err != nil {
257			t.Fatalf("use U-1: %v", err)
258		}
259		before, err := s.RequestHistory("r1")
260		if err != nil {
261			t.Fatalf("request history r1: %v", err)
262		}
263	
264		// 查询本身不接收当前时刻，也就不能借查询确认任何承诺到期；查询前后账目、
265		// 到期标记与预留历史必须保持原样。
266		us, err := s.CommitmentUsages("cMain")
267		if err != nil {
268			t.Fatalf("commitment usages cMain: %v", err)
269		}
270		if len(us) != 1 || us[0] != (Usage{ID: "U-1", CommitmentID: "cMain", Quantity: 2}) {
271			t.Fatalf("usages = %+v, want only {U-1 cMain 2}", us)
272		}
273	
274		// 篡改返回结果：改编号、改数量、删首条、追加假记录。
275		us[0].ID = "U-hacked"
276		us[0].Quantity = 99
277		us = append(us[1:], Usage{ID: "U-fake", CommitmentID: "cMain", Quantity: 4})
278	
279		// 真实记录、已用数量与后续查询不受篡改影响。
280		again, err := s.CommitmentUsages("cMain")
281		if err != nil {
282			t.Fatalf("commitment usages again: %v", err)
283		}
284		if len(again) != 1 || again[0] != (Usage{ID: "U-1", CommitmentID: "cMain", Quantity: 2}) {
285			t.Fatalf("usages after caller mutation = %+v, want only {U-1 cMain 2}", again)
286		}
287		if c := mustCommitment(t, s, "cMain"); c.Used != 2 {
288			t.Fatalf("cMain used = %d after caller mutation, want 2", c.Used)
289		}
290		if got, err := s.Use("U-1", "cMain", 2, nowOK); err != nil || got.Quantity != 2 {
291			t.Fatalf("U-1 retry after caller mutation = %+v err %v, want two-piece record", got, err)
292		}
293	
294		// 只读性：实物、占用、可承诺不变；cMain 未因查询被确认到期；历史未追加。
295		assertPartAccount(t, s, 18, 9, 9)
296		if c := mustCommitment(t, s, "cMain"); c.Expired || c.Canceled {
297			t.Fatalf("query confirmed expiry or cancel: %+v", c)
298		}
299		after, err := s.RequestHistory("r1")
300		if err != nil {
301			t.Fatalf("request history r1 after query: %v", err)
302		}
303		if len(after) != len(before) {
304			t.Fatalf("history grew from %d to %d records due to query", len(before), len(after))
305		}
306	}
